#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  [[ -n "${LEDGER_SETUP_NO_BROWSER:-}" ]] && return 0
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  [[ " ${WRITTEN_ENV[*]:-} " == *" $key "* ]] || WRITTEN_ENV+=("$key")
  printf '  %s✓ remembered%s %s (for the next run)\n' "$GREEN" "$RESET" "$key"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "remembered for the next run: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# ── Ledger kit setup. Run it from anywhere: bash scripts/setup.sh ─────────
# Safe to re-run: every stage checks what is already done and skips or
# offers to replace it. It remembers only non-secret values, in .setup-state
# (gitignored). Secrets go straight into Cloudflare, never into a file.

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="$ROOT/.setup-state"
TOML="$ROOT/wrangler.toml"

# wrangler, run from worker/ against the shared config. LEDGER_SETUP_WRANGLER replaces it with
# another command — the rehearsal's fake (scripts/rehearse/fake-wrangler.cjs), never in a real install.
wrangler_cmd() { if [[ -n "${LEDGER_SETUP_WRANGLER:-}" ]]; then $LEDGER_SETUP_WRANGLER "$@"; else npx --no-install wrangler "$@"; fi; }
wr()  { (cd "$ROOT/worker" && wrangler_cmd "$@" -c ../wrangler.toml); }
wr0() { (cd "$ROOT/worker" && wrangler_cmd "$@"); }
# A JSON value out of stdin, with node (Node is required anyway): json_pick '<js expression on d>'.
json_pick() { node -e 'let s="";process.stdin.on("data",c=>s+=c).on("end",()=>{const at=[s.indexOf("["),s.indexOf("{")].filter(x=>x>=0);if(!at.length)return;let d;try{d=JSON.parse(s.slice(Math.min(...at)))}catch{return}let v;try{v=('"$1"')}catch{return}if(v!==undefined&&v!==null)process.stdout.write(String(v))})'; }
toml_get() { sed -nE "s/^$1 = \"(.*)\"$/\1/p" "$TOML" | head -n1; }
toml_set() { # toml_set KEY OLD NEW: replaces KEY = "OLD" with KEY = "NEW"
  node -e 'const fs=require("fs");const [f,k,o,n]=process.argv.slice(1);const s=fs.readFileSync(f,"utf8");const a=`${k} = "${o}"`;if(!s.includes(a)){process.exit(1)}fs.writeFileSync(f,s.replace(a,`${k} = "${n}"`))' "$TOML" "$1" "$2" "$3"
}
# words_of KEY: that catalogue entry (src/words.ts) in every language, one "<language><TAB><words>" line each;
# pick LANGUAGE ROWS: the one language's words out of them.
words_of() { (cd "$ROOT" && npx --no-install vite-node scripts/say.ts "$1" </dev/null 2>/dev/null) || true; }
pick() { printf '%s\n' "$2" | sed -n "s/^$1"$'\t'"//p" | head -n1; }
random_key() { node -e 'process.stdout.write(require("crypto").randomBytes(32).toString("hex"))'; }
secret_names() { { wr secret list --format json 2>/dev/null || wr secret list 2>/dev/null; } | json_pick 'd.map(x=>x.name).join(" ")' || true; }
has_secret() { [[ " $SECRETS " == *" $1 "* ]]; }
# put_secret NAME: wrangler asks the human for the value (hidden). Skips one already set unless they want it replaced.
put_secret() {
  local name="$1" what="$2"
  if has_secret "$name" && ! confirm "$name is already set. Replace it?"; then note "kept $name"; return 0; fi
  say "Type (or paste) ${BOLD}$what${RESET} when wrangler asks, then press Enter."
  note "Nothing appears while you type or paste — that is normal. Paste once, press Enter once."
  wr secret put "$name" && printf '  %s✓ set%s %s\n' "$GREEN" "$RESET" "$name"
}
# put_random NAME: a new 64-character random key, straight into Cloudflare. Echoes it for the human to keep.
put_random() {
  local name="$1" key
  key="$(random_key)"
  if printf '%s' "$key" | wr secret put "$name" >/dev/null; then printf '%s' "$key"; else return 1; fi
}

TOTAL_STAGES=14

banner "Ledger kit setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check this computer"
# 22.13 is the first Node with SQLite built in without a flag (the tests and the setup checks use it).
node_ok="$(node -p 'const [a,b]=process.versions.node.split(".").map(Number);a>22||(a===22&&b>=13)?1:0' 2>/dev/null || echo 0)"
if [[ "$node_ok" != 1 ]]; then
  warn "Node.js 22.13 or newer is needed (found: $(node --version 2>/dev/null || echo none))."
  open_url "https://nodejs.org/"
  say "Install the LTS version from nodejs.org, open a NEW Terminal window, and run this wizard again."
  exit 1
fi
note "Node $(node --version) ✓"
in_dir() { local d="$1"; shift; (cd "$d" && "$@"); }
# Quiet unless something fails: then the end of what it printed is shown (it holds no secret).
quietly() { # quietly "what" command…
  local what="$1" log; shift; log="$(mktemp)"
  if "$@" >"$log" 2>&1; then rm -f "$log"; return 0; fi
  warn "$what failed. The end of what it printed:"; tail -n 25 "$log" | sed 's/^/    /'; rm -f "$log"; return 1
}
for dir in "$ROOT" "$ROOT/worker"; do
  if [[ ! -d "$dir/node_modules" ]]; then
    say "Installing the code's building blocks in ${dir#"$ROOT"/}… (a minute)"
    quietly "Installing" in_dir "$dir" npm ci --no-audit --no-fund || exit 1
  fi
done
note "Building blocks installed ✓"
note "Already ran the tests in INSTALL.md step 2 and they passed? Answer n."
if confirm "Run the tests now (about a minute; recommended the first time)?"; then
  say "Testing… (about a minute)"
  quietly "The root tests" in_dir "$ROOT" npm test && quietly "The worker tests" in_dir "$ROOT/worker" npm test \
    && note "All tests pass ✓" \
    || { warn "Stop here and show your assistant (or a developer) the lines above."; exit 1; }
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "How the ledger reads your email"
say "Two ways (you can switch later by editing LEDGER_READER in wrangler.toml and deploying):"
step "${BOLD}subscription${RESET} — your Claude Pro/Max plan reads, through two scheduled routines at claude.ai/code. No per-use cost."
step "${BOLD}api${RESET} — the Claude API reads, paid per use from Anthropic credit (the ledger caps the daily spend)."
current_mode="$(toml_get LEDGER_READER)"
note "wrangler.toml says: $current_mode"
ask LEDGER_READER_MODE "Type subscription or api (Enter = $current_mode):"
LEDGER_READER_MODE="${LEDGER_READER_MODE:-$current_mode}"
case "$LEDGER_READER_MODE" in
  subscription|api) ;;
  *) warn "That is neither 'subscription' nor 'api'; keeping $current_mode."; LEDGER_READER_MODE="$current_mode" ;;
esac
[[ "$LEDGER_READER_MODE" != "$current_mode" ]] && toml_set LEDGER_READER "$current_mode" "$LEDGER_READER_MODE"
write_env LEDGER_READER_MODE "$LEDGER_READER_MODE"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Your home and language: currency, time zone, country, language"
say "The ledger keeps every total in ONE currency and counts days in ONE time zone — yours."
step "${BOLD}Currency${RESET}: the 3-letter code of the money you live in (SGD, EUR, USD, GBP, JPY, TWD, AUD …)."
step "${BOLD}Time zone${RESET}: where you live, as Region/City (Asia/Singapore, Europe/London, America/New_York …)."
step "${BOLD}Country${RESET}: its 2-letter code (SG, GB, DE, US, JP …); purchases outside it count as abroad (trips)."
step "${BOLD}Language${RESET}: the words of your page, alarms, iPhone replies and Claude's answers — ${BOLD}en${RESET} (English) or ${BOLD}zh-Hant${RESET} (Traditional Chinese). It can be changed later."
warn "Choose the currency carefully: once the ledger holds money it cannot change (start a new database for a new one)."
here_tz="$(node -p 'Intl.DateTimeFormat().resolvedOptions().timeZone' 2>/dev/null || true)"
here_cc="$(node -p '(new Intl.Locale(Intl.DateTimeFormat().resolvedOptions().locale).maximize().region)||""' 2>/dev/null || true)"
toml_home() { local v; v="$(toml_get "$1")"; [[ "$v" == REPLACE-WITH-YOUR-* ]] && v=""; printf '%s' "$v"; }
cur_ccy="$(toml_home LEDGER_HOME_CURRENCY)"; cur_tz="$(toml_home LEDGER_TIMEZONE)"; cur_cc="$(toml_home LEDGER_HOME_COUNTRY)"; cur_lang="$(toml_home LEDGER_LANGUAGE)"
# "EN", "zh-hant", "ZH-HANT" … → the spelling the worker takes; anything else is left for the check to refuse.
lang_tag() { case "$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]')" in en) printf 'en' ;; zh-hant) printf 'zh-Hant' ;; *) printf '%s' "$1" ;; esac; }
while :; do
  ask HOME_CURRENCY "Currency${cur_ccy:+ (Enter = $cur_ccy)}:"
  HOME_CURRENCY="$(printf '%s' "${HOME_CURRENCY:-$cur_ccy}" | tr '[:lower:]' '[:upper:]')"
  def_tz="${cur_tz:-$here_tz}"
  ask HOME_TIMEZONE "Time zone${def_tz:+ (Enter = $def_tz)}:"
  HOME_TIMEZONE="${HOME_TIMEZONE:-$def_tz}"
  def_cc="${cur_cc:-$here_cc}"
  ask HOME_COUNTRY "Country${def_cc:+ (Enter = $def_cc)}:"
  HOME_COUNTRY="$(printf '%s' "${HOME_COUNTRY:-$def_cc}" | tr '[:lower:]' '[:upper:]')"
  def_lang="${cur_lang:-en}"
  ask LANGUAGE "Language, en or zh-Hant (Enter = $def_lang):"
  LANGUAGE="$(lang_tag "${LANGUAGE:-$def_lang}")"
  # The same check the worker makes at every request (src/home.ts, src/words.ts).
  if problems="$(cd "$ROOT" && npx --no-install vite-node scripts/check-home.ts "$HOME_CURRENCY" "$HOME_TIMEZONE" "$HOME_COUNTRY" "$LANGUAGE" </dev/null 2>&1)"; then break; fi
  printf '%s\n' "$problems" | sed 's/^/  /'
  warn "Try again (Ctrl-C to stop)."
  HOME_CURRENCY=""; HOME_TIMEZONE=""; HOME_COUNTRY=""; LANGUAGE=""
done
if [[ -n "$cur_ccy" && "$cur_ccy" != "$HOME_CURRENCY" ]]; then
  warn "wrangler.toml already says $cur_ccy, and a ledger that holds money cannot change its currency."
  confirm "This ledger is still empty: change it to $HOME_CURRENCY?" || { HOME_CURRENCY="$cur_ccy"; note "kept $cur_ccy"; }
fi
for pair in "LEDGER_HOME_CURRENCY|$HOME_CURRENCY" "LEDGER_TIMEZONE|$HOME_TIMEZONE" "LEDGER_HOME_COUNTRY|$HOME_COUNTRY" "LEDGER_LANGUAGE|$LANGUAGE"; do
  key="${pair%%|*}"; want="${pair#*|}"; have="$(toml_get "$key")"
  [[ "$have" == "$want" ]] || { toml_set "$key" "$have" "$want" && printf '  %s✓ wrote%s %s = %s → wrangler.toml\n' "$GREEN" "$RESET" "$key" "$want"; }
done
# The starting categories in the owner's language: a category's name is shown as written, never
# translated. Only a list still exactly as the kit ships it (in either language) is swapped.
cur_cats="$(toml_get LEDGER_CATEGORIES)"
cat_rows="$(words_of categories.default)"
want_cats="$(pick "$LANGUAGE" "$cat_rows")"
if [[ -n "$want_cats" && "$cur_cats" != "$want_cats" ]] && { [[ "$cur_cats" == "$(pick en "$cat_rows")" ]] || [[ "$cur_cats" == "$(pick zh-Hant "$cat_rows")" ]]; }; then
  toml_set LEDGER_CATEGORIES "$cur_cats" "$want_cats" && printf '  %s✓ wrote%s LEDGER_CATEGORIES = %s → wrangler.toml\n' "$GREEN" "$RESET" "$want_cats"
fi
write_env HOME_CURRENCY "$HOME_CURRENCY"; write_env HOME_TIMEZONE "$HOME_TIMEZONE"; write_env HOME_COUNTRY "$HOME_COUNTRY"; write_env LANGUAGE "$LANGUAGE"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare account on the Workers Paid plan"
say "The ledger lives in your own Cloudflare account. It needs the ${BOLD}Workers Paid${RESET} plan (US\$5/month):"
say "the free plan's 10 ms of CPU per run cannot open a statement PDF."
open_url "https://dash.cloudflare.com/sign-up"
step "Sign up (or sign in) at dash.cloudflare.com."
step "In the dashboard: Workers & Pages → Plans (or Compute → Workers → Plans) → choose Workers Paid."
step "Then open Workers & Pages once: a new account offers to choose its workers.dev subdomain — any short name."
note "Already on Workers Paid? Just press Enter."
pause "Press Enter when your account is on Workers Paid."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Let this computer use your Cloudflare account"
if wr0 whoami 2>/dev/null | grep -qi "associated with the email"; then
  note "Already signed in:"; wr0 whoami 2>/dev/null | grep -i "email" | head -n1 | sed 's/^/  /'
  if confirm "Sign in with a DIFFERENT Cloudflare account instead?"; then wr0 logout >/dev/null 2>&1 || true; wr0 login; fi
else
  say "A browser window opens: sign in to Cloudflare and press ${BOLD}Allow${RESET}."
  wr0 login
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Create the database and the sign-in store"
db_id="$(wr d1 list --json 2>/dev/null | json_pick 'd.find(x=>x.name==="ledger-db")?.uuid')"
if [[ -z "$db_id" ]]; then
  say "Creating the database ledger-db… (if wrangler asks whether to add it to your config, answer ${BOLD}n${RESET}: this wizard does that)"
  wr0 d1 create ledger-db
  db_id="$(wr d1 list --json 2>/dev/null | json_pick 'd.find(x=>x.name==="ledger-db")?.uuid')"
fi
[[ -n "$db_id" ]] || { warn "Could not find the database id. Run 'npx wrangler d1 list' in the worker folder and tell your assistant what it says."; exit 1; }
note "database ledger-db: $db_id"
kv_id="$(wr0 kv namespace list 2>/dev/null | json_pick 'd.find(x=>x.title==="LEDGER_OAUTH"||x.title.endsWith("-LEDGER_OAUTH"))?.id')"
if [[ -z "$kv_id" ]]; then
  say "Creating the sign-in store LEDGER_OAUTH…"
  wr0 kv namespace create LEDGER_OAUTH
  kv_id="$(wr0 kv namespace list 2>/dev/null | json_pick 'd.find(x=>x.title==="LEDGER_OAUTH"||x.title.endsWith("-LEDGER_OAUTH"))?.id')"
fi
[[ -n "$kv_id" ]] || { warn "Could not find the sign-in store's id. Run 'npx wrangler kv namespace list' in the worker folder and tell your assistant."; exit 1; }
note "sign-in store LEDGER_OAUTH: $kv_id"
for pair in "database_id|$db_id" "id|$kv_id"; do
  key="${pair%%|*}"; want="${pair#*|}"; have="$(toml_get "$key")"
  if [[ "$have" == "$want" ]]; then continue; fi
  if [[ "$have" == REPLACE-WITH-YOUR-* ]] || confirm "wrangler.toml has $key = $have. Replace it with $want?"; then
    toml_set "$key" "$have" "$want" && printf '  %s✓ wrote%s %s → wrangler.toml\n' "$GREEN" "$RESET" "$key"
  fi
done
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Set up the database's tables"
say "Applying the migrations to your Cloudflare database (answer ${BOLD}y${RESET} if asked). Already applied ones are skipped."
wr d1 migrations apply ledger-db --remote
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Your banks, cards and accounts"
if [[ ! -f "$ROOT/seed/accounts.json" ]]; then
  cp "$ROOT/seed/accounts.example.json" "$ROOT/seed/accounts.json"
  say "Made seed/accounts.json from the example. It holds made-up banks and accounts: replace them with yours."
  step "Open seed/accounts.json in a text editor (or ask your assistant to write it with you)."
  step "Under ${BOLD}banks${RESET}: each bank you have, with EVERY mail domain it sends alerts and statements from (docs/adding-a-bank.md)."
  step "Under ${BOLD}accounts${RESET}: one entry per card, bank account and wallet you have; delete the rest. docs/accounts.md explains each field."
  note "This file stays on your computer (git ignores it). It holds only the last 4 digits of each card."
  pause "Press Enter when seed/accounts.json lists your own accounts."
fi
until (cd "$ROOT" && npm run -s seed:sql); do
  warn "Fix what is listed above in seed/accounts.json, save it, then press Enter to check again (Ctrl-C to stop)."
  pause
done
if grep -q "DBS account 0001\|HSBC card 0003\|Citi card 0004" "$ROOT/seed/accounts.json"; then
  warn "seed/accounts.json still holds example accounts (0001, 0003, 0004)."
  confirm "Load it anyway?" || { say "Edit seed/accounts.json, then run this wizard again."; exit 1; }
fi
say "Loading your accounts into the database (safe to repeat: nothing is added twice)…"
wr d1 execute ledger-db --remote --file ../seed/accounts.sql
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Put the ledger online"
say "Deploying. On a new Cloudflare account wrangler asks to register a ${BOLD}workers.dev subdomain${RESET}:"
say "answer ${BOLD}y${RESET}, then type any short name (letters, digits, dashes). Your address becomes"
say "https://ledger.<that-name>.workers.dev."
# The deploy runs straight in this terminal, never through a pipe: wrangler asks its subdomain question
# only when its output IS a terminal; through a pipe it answers "no" by itself and stops. The address is
# read from wrangler's own record of the deploy (WRANGLER_OUTPUT_FILE_PATH), not from the screen.
deploy_record="$(mktemp)"
if ! (export WRANGLER_OUTPUT_FILE_PATH="$deploy_record"; wr deploy); then
  rm -f "$deploy_record"
  printf '\n'; warn "The ledger is not online yet."
  say "If wrangler said you need to ${BOLD}register a workers.dev subdomain${RESET}: open https://dash.cloudflare.com →"
  say "${BOLD}Workers & Pages${RESET} (or Compute → Workers), choose a workers.dev subdomain when it offers one,"
  say "then run this wizard again: ${BOLD}bash scripts/setup.sh${RESET} — it skips everything already done."
  say "Anything else: show your assistant the red lines above (they hold no secret)."
  exit 1
fi
found="$(node -e 'const fs=require("fs");const out=fs.readFileSync(process.argv[1],"utf8").split("\n").filter(Boolean).map(l=>{try{return JSON.parse(l)}catch{return {}}}).filter(e=>e.type==="deploy").pop();const u=((out&&out.targets)||[]).find(t=>/^https:\/\/[a-z0-9.-]+\.workers\.dev$/.test(t));if(u)process.stdout.write(u)' "$deploy_record" 2>/dev/null || true)"
rm -f "$deploy_record"
if [[ -n "$found" ]]; then
  LEDGER_ADDRESS="$found"
  note "Your ledger's address: $LEDGER_ADDRESS"
else
  ask LEDGER_ADDRESS "Your ledger's address — the https://ledger.….workers.dev line printed above:"
fi
LEDGER_ADDRESS="${LEDGER_ADDRESS%/}"
[[ "$LEDGER_ADDRESS" =~ ^https://[a-z0-9.-]+$ ]] || { warn "That does not look like https://ledger.<name>.workers.dev. Run the wizard again."; exit 1; }
write_env LEDGER_ADDRESS "$LEDGER_ADDRESS"
note "A brand-new address can show a security (SSL) error for a few minutes. Wait; it is normal."
pause

SECRETS="$(secret_names)"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Your three keys"
say "Three long random keys lock the ledger. Each one is made here and sent straight to Cloudflare."
warn "Keep the two shown below in your password manager. Never paste them into an AI chat."
new_unlock=""
if has_secret LEDGER_UNLOCK_KEY && ! confirm "The page key is already set. Make a new one (the old page link stops working)?"; then
  note "kept LEDGER_UNLOCK_KEY (lost it? run this again and answer y)"
else
  has_secret LEDGER_UNLOCK_KEY && new_unlock=1
  unlock="$(put_random LEDGER_UNLOCK_KEY)" || { warn "Cloudflare refused the key; nothing changed. Run the wizard again."; exit 1; }
  say "Your page link (open it once on your iPhone, then Add to Home Screen):"
  printf '\n    %s%s/unlock?key=%s%s\n\n' "$BOLD" "$LEDGER_ADDRESS" "$unlock" "$RESET"
  unlock=""
fi
# A browser that already opened the old link stays signed in (90 days) until this one changes.
if has_secret LEDGER_SESSION_SECRET && [[ -n "$new_unlock" ]] \
   && confirm "Also sign out every browser that opened the old link (yours too; Gmail is reconnected once on the page)?"; then
  put_random LEDGER_SESSION_SECRET >/dev/null && note "made a new LEDGER_SESSION_SECRET: every browser is signed out" \
    || { warn "Cloudflare refused LEDGER_SESSION_SECRET. Run the wizard again."; exit 1; }
elif has_secret LEDGER_SESSION_SECRET; then note "kept LEDGER_SESSION_SECRET"
elif put_random LEDGER_SESSION_SECRET >/dev/null; then note "set LEDGER_SESSION_SECRET (nobody ever types this one)"
else warn "Cloudflare refused LEDGER_SESSION_SECRET. Run the wizard again."; exit 1; fi
if has_secret LEDGER_SHORTCUT_KEY && ! confirm "The iPhone Shortcut key is already set. Make a new one (old Shortcuts stop working)?"; then
  note "kept LEDGER_SHORTCUT_KEY"
else
  shortcut="$(put_random LEDGER_SHORTCUT_KEY)" || { warn "Cloudflare refused the key; nothing changed. Run the wizard again."; exit 1; }
  say "Your iPhone Shortcut key (goes after 'Bearer ' in each Shortcut):"
  printf '\n    %s%s%s\n\n' "$BOLD" "$shortcut" "$RESET"
  shortcut=""
fi
pause "Saved both in your password manager? Press Enter (the screen clears)."

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Sign-in emails (Resend)"
say "The Claude connectors sign you in with a 6-digit code sent by email, through Resend (free)."
open_url "https://resend.com/api-keys"
step "Sign up at resend.com with the email address you want the codes sent to."
step "API Keys → Create API Key → name it Ledger → Sending access → copy the key (starts with re_)."
note "Resend's free sender only delivers to the address your Resend account is registered under."
# The address is asked in plain sight and read back: a typo here means the codes never arrive, and
# wrangler's own prompt hides what is typed. It is not a secret (Resend and you both know it).
if has_secret LEDGER_OWNER_EMAIL && ! confirm "LEDGER_OWNER_EMAIL is already set. Replace it?"; then
  note "kept LEDGER_OWNER_EMAIL"
else
  while :; do
    owner_email=""
    printf '  %sEmail address for the sign-in codes (the one your Resend account uses):%s ' "$BOLD" "$RESET"
    read -r owner_email || true
    owner_email="$(printf '%s' "$owner_email" | tr -d '[:space:]')"
    if [[ ! "$owner_email" =~ ^[^@]+@[^@]+\.[^@]+$ ]]; then warn "That is not an email address. Try again."; continue; fi
    confirm "The codes go to ${BOLD}$owner_email${RESET}${YELLOW} — is that exactly right?" && break
  done
  printf '%s' "$owner_email" | wr secret put LEDGER_OWNER_EMAIL >/dev/null && printf '  %s✓ set%s LEDGER_OWNER_EMAIL\n' "$GREEN" "$RESET"
fi
put_secret RESEND_API_KEY "the Resend API key"
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Let the ledger read your Gmail (Google)"
say "Create a Google sign-in client. INSTALL.md step 6 has every click; your assistant can walk you through it."
say "You will need these three values:"
printf '    Authorised redirect URI:  %s%s/google/callback%s\n' "$BOLD" "$LEDGER_ADDRESS" "$RESET"
printf '    Privacy policy link:      %s%s/privacy%s\n' "$BOLD" "$LEDGER_ADDRESS" "$RESET"
printf '    Authorised domain:        %s%s%s\n' "$BOLD" "${LEDGER_ADDRESS#https://ledger.}" "$RESET"
open_url "https://console.cloud.google.com/"
pause "Press Enter when you have the Client ID and Client secret."
put_secret GMAIL_CLIENT_ID "the Client ID (ends with .apps.googleusercontent.com)"
put_secret GMAIL_CLIENT_SECRET "the Client secret"
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Claude API key (api mode only)"
if [[ "$LEDGER_READER_MODE" == "api" ]]; then
  open_url "https://platform.claude.com/"
  step "Billing → buy credit (US\$25 is plenty to start)."
  step "Settings → Limits → set a monthly spend limit (your backstop)."
  step "API keys → Create key → name it Ledger → copy it."
  put_secret ANTHROPIC_API_KEY "the Anthropic API key (starts with sk-ant-)"
  note "Then set LEDGER_API_CREDIT_USD and LEDGER_API_CREDIT_SINCE in wrangler.toml to what you bought and today's date,"
  note "and deploy once more: npm run deploy, in the worker folder."
else
  note "Subscription mode: no API key. The two claude.ai routines do the reading (INSTALL.md step 9)."
fi
pause

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Statement PDF passwords"
say "Most banks lock the statement PDFs they email with a password (often an ID or birth date)."
say "For each bank: ${BOLD}y${RESET} = locked, type the password now · ${BOLD}n${RESET} = its PDFs open without one · Enter = not sure, skip."
note "A skipped or wrong password loses nothing: the statement waits on the page (To review → Passwords)."
# One line per bank: id <tab> name <tab> NAME_IN_CAPITALS <tab> unlocked (1/0) <tab> on the bank list (1/0).
# GrabPay is not on the bank list; its PDFs are read locked or not, so only a password is asked.
bank_rows="$(node -e '
  const s = JSON.parse(require("fs").readFileSync(process.argv[1], "utf8"));
  const up = (i) => i.toUpperCase().replace(/[^A-Z0-9]+/g, "_");
  const rows = (s.banks || []).map((b) => [b.institution, b.name || b.institution, up(b.institution), b.pdf_password === false ? 1 : 0, 1]);
  if ((s.accounts || []).some((a) => a.institution === "grab")) rows.push(["grab", "GrabPay", "GRAB", 0, 0]);
  for (const r of rows) console.log(r.join("\t"));' "$ROOT/seed/accounts.json")"
unlocked_written=""
while IFS=$'\t' read -r b_id b_name b_up b_unlocked b_listed <&3; do
  [[ -n "$b_id" ]] || continue
  name="LEDGER_PDF_PW_$b_up"
  if [[ "$b_unlocked" == 1 ]]; then note "$b_name: your accounts file says its statements are not locked ✓"; continue; fi
  if has_secret "$name"; then note "$b_name: password already set ($name) ✓"; continue; fi
  printf '  %s? %s: are its statement PDFs locked with a password? (y / n / Enter = skip):%s ' "$YELLOW" "$b_name" "$RESET"
  pdf_answer=""; read -r pdf_answer || true
  case "$pdf_answer" in
    [Yy]*) put_secret "$name" "the $b_name statement PDF password" ;;
    [Nn]*)
      if [[ "$b_listed" == 1 ]]; then
        # A bank's statement is refused when it arrives unlocked, unless the list says this bank sends them
        # so (worker/src/pipeline.ts): write that, and load the list again.
        node -e '
          const fs = require("fs"), [f, id] = process.argv.slice(1);
          const s = JSON.parse(fs.readFileSync(f, "utf8"));
          for (const b of s.banks) if (b.institution === id) b.pdf_password = false;
          fs.writeFileSync(f, JSON.stringify(s, null, "\t") + "\n");' "$ROOT/seed/accounts.json" "$b_id"
        printf '  %s✓ wrote%s "pdf_password": false for %s → seed/accounts.json\n' "$GREEN" "$RESET" "$b_name"
        note "Only PDFs from $b_name's own mail domains, vouched for by Gmail, are read as its statements."
        unlocked_written=1
      else
        note "$b_name: nothing to set."
      fi ;;
    *) note "skipped $b_name" ;;
  esac
done 3<<<"$bank_rows"
if [[ -n "$unlocked_written" ]]; then
  say "Loading the changed bank list…"
  (cd "$ROOT" && npm run -s seed:sql) && wr d1 execute ledger-db --remote --file ../seed/accounts.sql >/dev/null \
    && note "Bank list loaded ✓" \
    || warn "Could not load it. Run the wizard again (stage 8 loads seed/accounts.json)."
fi
pause

finish
say "Your ledger: ${BOLD}$LEDGER_ADDRESS${RESET}"
say "Next (INSTALL.md steps 7–11, with your assistant):"
[[ "$LANGUAGE" == "zh-Hant" ]] && home_screen="Share → Add to Home Screen (分享 → 加入主畫面)" || home_screen="Share → Add to Home Screen"
connect_gmail="$(pick "$LANGUAGE" "$(words_of ui.connect_gmail)")"
step "Open your page link in Safari on your iPhone → $home_screen → tap ${BOLD}${connect_gmail:-Connect Gmail}${RESET}."
step "claude.ai → Settings → Connectors: add ${BOLD}Ledger${RESET} = $LEDGER_ADDRESS/mcp"
[[ "$LEDGER_READER_MODE" == "subscription" ]] && step "Also add ${BOLD}Ledger Reader${RESET} = $LEDGER_ADDRESS/mcp-reader, then the two routines (routines/)."
[[ "$LEDGER_READER_MODE" == "api" ]] && step "Wait for the dry-run email, then approve the price (INSTALL.md step 9, api mode)."
step "Build the iPhone Shortcuts: docs/iphone-shortcuts.md."
printf '\n'
